async function request(path,{method='GET',params,body,auth=true,pending=false,signal}={}){
 if(!/^\/(?:token$|api\/[A-Za-z0-9/_]+$)/.test(path))throw Error('接口路径无效');const account=active();if(auth&&!account){if(vault.expired)expire();throw Error('请先登录舞立方账号');}
 const controller=new AbortController(),cancel=()=>controller.abort();if(signal?.aborted)controller.abort();signal?.addEventListener('abort',cancel,{once:true});controller.apiReadOnly=method==='GET';requestControllers.add(controller);const timeout=setTimeout(()=>controller.abort(),20000);
 const url=new URL(A.BASE+path);if(params)for(const[k,v]of Object.entries(params))url.searchParams.set(k,String(v));const headers={Accept:'application/json'};if(auth)headers.Authorization='bearer '+account.token;if(body instanceof URLSearchParams)headers['Content-Type']='application/x-www-form-urlencoded';else if(body!==undefined)headers['Content-Type']='application/json';
 const previous=apiGate;let releaseSlot;apiGate=new Promise(resolve=>releaseSlot=resolve);try{await previous;if(controller.signal.aborted)throw new DOMException('Cancelled','AbortError');await new Promise(resolve=>setTimeout(resolve,Math.max(0,apiNext-Date.now())));if(controller.signal.aborted)throw new DOMException('Cancelled','AbortError');apiNext=Date.now()+400;const response=await fetch(url.href,{method,headers,body:body===undefined?undefined:body instanceof URLSearchParams?body:JSON.stringify(body),mode:'cors',credentials:'omit',cache:'no-store',referrerPolicy:'no-referrer',signal:controller.signal});const text=await response.text();let data=text;try{data=text?JSON.parse(text):null;}catch{}
  if((response.status===401||data?.error==='invalid_token')&&!pending){if(auth)expire();throw Error('登录已失效，请重新登录');}if(pending&&[400,401].includes(response.status)&&['invalid_client','authorization_pending','invalid_grant',undefined].includes(data?.error))return null;
  if(!response.ok||data?.error){const reason=typeof data==='object'?(data?.Message||data?.message||data?.error_description||''):'';throw Error(String(reason||'官方接口返回 '+response.status).slice(0,220));}return data;
 }catch(e){if(e.name==='AbortError')throw Error('请求已取消或超时，可重试');if(e instanceof TypeError)throw Error('无法连接官方接口；请检查网络或跨域限制后重试');throw e;}finally{releaseSlot();clearTimeout(timeout);requestControllers.delete(controller);signal?.removeEventListener('abort',cancel);}
}
