 const allowed=()=>{if(!$('dcLoginAgree').checked)throw Error('请先阅读并勾选法律与数据说明');};
 $('dcQrTab').onclick=()=>{clearInterval(smsTimer);$('dcPhoneForm').hidden=true;$('dcQrForm').hidden=false;$('dcQrTab').classList.add('active');$('dcPhoneTab').classList.remove('active');};$('dcPhoneTab').onclick=()=>{stopQR();$('dcQrForm').hidden=true;$('dcPhoneForm').hidden=false;$('dcPhoneTab').classList.add('active');$('dcQrTab').classList.remove('active');};
 $('dcQrGenerate').onclick=async()=>{try{allowed();stopQR();const run=qrRun,btn=$('dcQrGenerate');btn.disabled=true;status('正在请求官方二维码…');try{const data=await request('/api/Common/GetQrCode',{auth:false});if(run!==qrRun||!$('dcQrForm'))return;const url=A.mediaURL(data?.QrcodeUrl,{qr:true});if(!url||!data.ID)throw Error('官方没有返回可识别的二维码');qrId=String(data.ID);qrDeadline=Math.min(Date.now()+180000,A.dateValue(data.ExpireTime)||Infinity);$('dcQrFrame').innerHTML=`<img id="dcQrImage" src="${e(url)}" referrerpolicy="no-referrer" alt="舞立方官方登录二维码">`;status('请使用微信扫描并确认登录');$('dcQrStatus').textContent='二维码最多等待 3 分钟。微信确认后回到此页，登录状态将自动更新。';pollQR(run);decodeWeChatLink(url,run);}finally{if($('dcQrGenerate'))$('dcQrGenerate').disabled=false;}}catch(err){status(err.message);}};
 $('dcCaptcha').onclick=async()=>{try{allowed();const phone=phoneValue();$('dcCaptcha').disabled=true;const data=await request('/api/Common/GetGraphCode',{auth:false,params:{phone}});if(!$('dcPhoneForm'))return;const value=String(data||'').replace(/^data:image\/[a-z]+;base64,/,'');if(!/^[A-Za-z0-9+/=\r\n]+$/.test(value)||value.length>200000)throw Error('验证码图片格式无效');$('dcCaptchaImg').src='data:image/gif;base64,'+value;$('dcCaptchaImg').hidden=false;status('请填写图片中的验证码');}catch(err){status(err.message);}finally{if($('dcCaptcha'))$('dcCaptcha').disabled=false;}};
