function phoneValue(){const value=$('dcPhone').value.trim();if(!/^1[3-9]\d{9}$/.test(value))throw Error('请输入正确的本人手机号');return value;}
function startSmsCountdown(){clearInterval(smsTimer);function tick(){if(!$('dcSendSms')){clearInterval(smsTimer);return;}const remaining=Math.max(0,Math.ceil((smsUntil-Date.now())/1000));$('dcSendSms').disabled=remaining>0;$('dcSendSms').textContent=remaining?remaining+' 秒后可重试':'发送短信验证码';if(!remaining)clearInterval(smsTimer);}tick();if(Date.now()<smsUntil)smsTimer=setInterval(tick,1000);}
async function decodeWeChatLink(url,run){if(!('BarcodeDetector'in root))return;try{const response=await fetch(url,{credentials:'omit',referrerPolicy:'no-referrer'}),blob=await response.blob(),bitmap=await createImageBitmap(blob),detector=new BarcodeDetector({formats:['qr_code']}),codes=await detector.detect(bitmap);bitmap.close();const candidate=new URL(codes[0]?.rawValue);if(!['weixin.qq.com','open.weixin.qq.com'].includes(candidate.hostname)||!['http:','https:'].includes(candidate.protocol))return;if(run!==qrRun||!$('dcWeChatOpen'))return;qrLink=candidate.href;$('dcWeChatOpen').href=qrLink;$('dcWeChatOpen').hidden=false;}catch{}}
async function pollQR(run){if(qrPollingRun===run||run!==qrRun||!qrId||!$('dcQrForm')||$('dcQrForm').hidden)return;if(Date.now()>=qrDeadline){stopQR();status('二维码已到期，请刷新后扫码');return;}qrPollingRun=run;try{const data=await request('/token',{method:'POST',auth:false,pending:true,body:new URLSearchParams({client_type:'qrcode',grant_type:'client_credentials',client_id:qrId})});if(run!==qrRun)return;if(data?.access_token){await loginSuccess(data);return;}}catch(err){if(run===qrRun)status(err.message+'；仍可刷新二维码重试');}finally{if(qrPollingRun===run)qrPollingRun=null;}if(run===qrRun)qrTimer=setTimeout(()=>pollQR(run),2500);}
