async function loadBag(force=false){if(cache.bag&&!force)return;const collected=[];let page=1,total=Infinity;while(collected.length<total&&page<=100){const data=await request('/api/User/GetMyBagMusic',{params:{page,pagesize:100}}),batch=A.list(data);collected.push(...batch);total=Number(data?.RecordCount)||collected.length;if(batch.length<100)break;page++;status('正在读取背包 '+collected.length+' / '+total);}if(page>100)throw Error('背包超过 10000 项，当前未载入完整列表');machineSelection=A.list(await request('/api/User/GetMyMusicForSelect'));bagItems=A.mergeSelection(collected,machineSelection);cache.bag=true;}
function renderBag(){content().innerHTML=`<div class="account-list-heading"><div><h4>自制谱背包 <span>${bagItems.length}</span></h4><p>有效期、机台显示与下架状态取自官方；已下架资源仍可尝试导出备份。</p></div><button id="bagRefresh">刷新背包</button></div><div class="bag-filters"><input id="bagQuery" placeholder="搜索曲名 / ID / 谱师" value="${hooks.esc(bagQuery)}" aria-label="搜索背包"><label>上架状态<select id="bagAvailability"><option value="all">全部</option><option value="unlisted">已下架</option><option value="listed">仍在售</option><option value="unknown">状态未提供</option></select></label><label>第一优先<select id="bagSort1">${sortOptions(sortPrimary)}</select></label><select id="bagDir1" aria-label="第一优先顺序"><option value="asc">升序 / 优先显示</option><option value="desc">降序 / 优先隐藏</option></select><label>第二优先<select id="bagSort2">${sortOptions(sortSecondary)}</select></label><select id="bagDir2" aria-label="第二优先顺序"><option value="asc">升序 / 优先显示</option><option value="desc">降序 / 优先隐藏</option></select></div><div id="bagCards" class="music-cards compact-song-cards"></div>`;$('bagAvailability').value=bagAvailability;$('bagAvailability').onchange=e=>{bagAvailability=e.target.value;bagPage=1;drawBag();};$('bagDir1').value=sortDir1;$('bagDir2').value=sortDir2;
 $('bagQuery').oninput=e=>{bagQuery=e.target.value;bagPage=1;drawBag();};for(const id of ['bagSort1','bagSort2','bagDir1','bagDir2'])$(id).onchange=()=>{sortPrimary=$('bagSort1').value;sortSecondary=$('bagSort2').value;sortDir1=$('bagDir1').value;sortDir2=$('bagDir2').value;drawBag();};$('bagRefresh').onclick=async()=>{delete cache.bag;detailQueue.clear();render();};drawBag();}
